import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DncwoWA8.js";const u=JSON.parse('{"title":"Choose your starting point","description":"","frontmatter":{},"headers":[],"relativePath":"guide/start.md","filePath":"guide/start.md"}'),o={name:"guide/start.md"};function r(l,e,n,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="choose-your-starting-point" tabindex="-1">Choose your starting point <a class="header-anchor" href="#choose-your-starting-point" aria-label="Permalink to &quot;Choose your starting point&quot;">​</a></h1><p>Pick the task you have now. You do not need to run every skill or complete a fixed lifecycle.</p><ul><li><a href="/projects/ai-skills/workflows/plan-a-project.html">Plan a project or feature</a> when requirements, outcomes, or limitations are unsettled. Finish with agreed scope and verifiable tasks, or the requested earlier planning result.</li><li><a href="/projects/ai-skills/workflows/implement-a-task.html">Implement a planned task</a> when a task is defined and approved. Finish with tested behavior, documentation impact, and review evidence.</li><li><a href="/projects/ai-skills/workflows/debug-a-problem.html">Debug an application problem</a> when behavior is incorrect. Finish with an evidence-backed cause and verified fix, or a precise blocker.</li><li><a href="/projects/ai-skills/workflows/document-a-project.html">Document a project</a> when a project needs a usable documentation website. Finish with checked reader tasks, examples, reference, and navigation.</li><li><a href="/projects/ai-skills/workflows/debloat-a-project.html">Debloat a project</a> when existing complexity needs to justify its cost. Finish with safe reductions or evidence for keeping the current design.</li></ul><p>Need skills installed first? Use <a href="/projects/ai-skills/guide/install.html">installation choices</a>. Need one skill rather than a full journey? Use the <a href="/projects/ai-skills/skills/">skill reference</a>. Workspace safeguards, independent review, retrospectives, and diagrams are in <a href="/projects/ai-skills/workflows/supporting-tools.html">supporting tools</a>.</p><h2 id="start-small" tabindex="-1">Start small <a class="header-anchor" href="#start-small" aria-label="Permalink to &quot;Start small&quot;">​</a></h2><ol><li>Read the skill profile and its linked authoritative instructions.</li><li>Check its declared instruction requirements separately from runtime and harness setup.</li><li>Use the profile&#39;s single-skill install command through the project&#39;s reviewed process. You do not need the complete collection or the optional manager.</li><li>Make one bounded request and verify that the harness loaded the intended guidance.</li><li>Stop at the requested result. Decide separately whether another phase is useful.</li></ol><p>The <a href="/projects/ai-skills/guide/first-use.html">first-use exercise</a> gives you a read-only starting request. The <a href="/projects/ai-skills/workflows/">project workflows</a> explain skill handoffs, optional branches, correction loops, and explicit stopping points.</p><h2 id="if-you-are-maintaining-the-collection" tabindex="-1">If you are maintaining the collection <a class="header-anchor" href="#if-you-are-maintaining-the-collection" aria-label="Permalink to &quot;If you are maintaining the collection&quot;">​</a></h2><p>Use <a href="/projects/ai-skills/maintenance/">site maintenance</a> for mise tasks, generated pages, catalog coverage, and validation. The YAML catalog remains the authored inventory; this website is a learning and reference layer.</p>',9)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
